def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: number of nanoseconds since the start of the day
    :param tz: optional timezone information (datetime.tzinfo or numeric hours offset)
    :return: datetime.time object
    """
    # Ensure nanoseconds is an integer
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise ValueError(f"nanoseconds must be an integer or convertible to int: {exc}") from exc

    if ns < 0:
        raise ValueError("nanoseconds must be non‑negative")

    # Break down nanoseconds into time components
    total_seconds, remaining_ns = divmod(ns, 1_000_000_000)
    hour, rem = divmod(total_seconds, 3600)
    minute, second = divmod(rem, 60)
    microsecond = remaining_ns // 1_000  # convert remaining ns to µs (floor)

    # Resolve timezone information
    tzinfo = None
    if tz is not None:
        # If tz is already a tzinfo object, use it directly
        if hasattr(tz, 'utcoffset') and callable(tz.utcoffset):
            tzinfo = tz
        else:
            # Assume tz can be interpreted as hour offset (float or int)
            try:
                offset_hours = float(tz)
                tzinfo = datetime.timezone(datetime.timedelta(hours=offset_hours))
            except Exception:
                # If tz cannot be interpreted, ignore it and treat as naive time
                tzinfo = None

    try:
        return datetime.time(hour, minute, second, microsecond, tzinfo=tzinfo)
    except Exception as exc:
        # Raise a descriptive error if constructing the time fails
        raise ValueError(f"Unable to hydrate time from nanoseconds {nanoseconds}: {exc}") from exc

