    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels.
    """
    # Local regular expressions for label keys and values.
    import re

    KEY_REGEX = r'^[A-Za-z][A-Za-z0-9_-]{0,127}$'
    VALUE_REGEX = r'^[A-Za-z0-9 _.-]{1,250}$'

    if not isinstance(labels, dict):
        raise ValidationError({"labels": "Labels must be a dictionary"})

    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): "expected string or bytes-like object"})
            key_str = str(key)  # keep string representation for regex error message
        else:
            key_str = key

        # Validate key regex
        if isinstance(key_str, str) and not re.match(KEY_REGEX, key_str):
            messages.append(
                {key_str: f"Label key '{key_str}' does not match the regex [{KEY_REGEX}]"}
            )

        # Helper to validate a single value entry
        def _validate_value_entry(entry, container_key=None):
            if not isinstance(entry, (str, bytes)):
                # Path representation for list elements
                path = f"{container_key}[{repr(entry)}]" if container_key else repr(entry)
                messages.append({path: "expected string or bytes-like object"})
                return
            # Validate value regex
            if not re.match(VALUE_REGEX, entry):
                path = f"{container_key}[{repr(entry)}]" if container_key else entry
                messages.append(
                    {path: f"Label value '{entry}' does not match the regex [{VALUE_REGEX}]"}
                )

        # Validate value
        if isinstance(value, (list, tuple)):
            for idx, entry in enumerate(value):
                _validate_value_entry(entry, f"{key_str}[{idx}]")
        else:
            _validate_value_entry(value, key_str)

    if messages:
        raise ValidationError(messages)

