def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                filename = info.filename
                base = os.path.splitext(os.path.basename(filename))[0]
                data = zf.read(info)
                if base not in result:
                    result[base] = {}
                result[base][filename] = data
    except (FileNotFoundError, zipfile.BadZipFile) as e:
        raise RuntimeError(f"Failed to read zip file {zip_path}: {e}") from e
    return result

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`"""
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Collect only actual file entries, skip directories
            names = [info.filename for info in zf.infolist() if not info.is_dir()]
    except (FileNotFoundError, zipfile.BadZipFile, OSError):
        # Return an empty list if the file cannot be read or is not a zip
        return []
    return names

