def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        import json
        # Determine a sensible indent level
        actual_indent = indent if indent and indent > 0 else 4
        if hasattr(self, "__dict__"):
            data = self.__dict__
            rep = json.dumps(data, indent=actual_indent, sort_keys=True, default=lambda o: str(o))
