    # Normalise spec_option to a list of lower‑case extensions
    def _parse_spec(opt):
        if isinstance(opt, str):
            if opt.lower() in ("ini", "input"):
                return {".ini"}
            if opt.lower() == "all":
                return None
            # Treat arbitrary string as one extension
            return {opt.lower() if opt.lower().startswith(".") else f".{opt.lower()}"}
        if isinstance(opt, (list, set, tuple)):
            exts = set()
            for e in opt:
                if not isinstance(e, str):
                    raise ValueError(f"Extension must be string, got {e!r}")
                exts.add(e.lower() if e.lower().startswith(".") else f".{e.lower()}")
            return exts
        raise ValueError(f"Invalid spec_option type: {type(opt).__name__}")

    try:
