    """
    Resolve the include directive in spec files.
    The directive is expected to be a dictionary entry with the key
    ``__include__`` whose value is either:
      * a path to a JSON file containing a dictionary to merge
      * a dictionary that should be merged directly into the current
        config.

    The method recursively processes nested include directives and
    protects against circular references by tracking the files that
    have already been processed.  In case of any failure a
    ``RuntimeError`` is raised with a helpful message.
    """
    import json
    import os

    # Map of absolute file paths that have already been processed.
    _processed_files = set()

    def _merge_dicts(base, new, path_stack):
        """
        Deeply merge ``new`` into ``base``.  New values overwrite old
        values when the same key is present.  Keys that are dictionaries
        are merged recursively.  Circular references are detected via
        ``path_stack``.
        """
        for key, val in new.items():
            if key in base and isinstance(base[key], dict) and isinstance(val, dict):
                base[key] = _merge_dicts(base[key], val, path_stack)
            else:
                base[key] = val
        return base

    def _process_node(node_repr, current_path, path_stack):
        """
        Process a node that may contain an include directive.
        ``node_repr`` is expected to be a dictionary.
        """
        if not isinstance(node_repr, dict):
            # Nothing to include; return as-is.
            return node_repr

        # Detect a direct include dict.
        if "__include__" in node_repr:
            include = node_repr["__include__"]
            if isinstance(include, dict):
                # Merge the provided dictionary.
                resolved = {}
                for sub_k, sub_v in include.items():
                    resolved[sub_k] = _process_node(sub_v, current_path, path_stack)
                # Merge into current node (excluding the include key).
                node_to_merge = dict(node_repr)
                node_to_merge.pop("__include__")
                return _merge_dicts(resolved, node_to_merge, path_stack)
            elif isinstance(include, str):
                # Treat the string as a file path.
                inc_path = os.path.abspath(
                    include if os.path.isabs(include)
                    else os.path.join(os.path.dirname(current_path), include)
                )
                if inc_path in _processed_files:
                    raise RuntimeError(f"Circular include detected: {inc_path}")
                if not os.path.isfile(inc_path):
                    raise FileNotFoundError(f"Included file not found: {inc_path}")
                try:
                    with open(inc_path, "r") as f:
                        inc_content = json.load(f)
                except Exception as exc:
                    raise RuntimeError(f"Failed to load include file {inc_path}") from exc
                _processed_files.add(inc_path)
                node_to_merge = dict(node_repr)
                node_to_merge.pop("__include__")
                merged = _merge_dicts(
                    _process_node(inc_content, inc_path, path_stack + (inc_path,)),
                    node_to_merge,
                    path_stack + (inc_path,),
                )
                _processed_files.discard(inc_path)
                return merged
            else:
                # Unsupported include form.
                raise RuntimeError(
                    f"Unsupported include type {type(include)!r} in {node_repr!r}"
                )

        # No include directive; recurse into dict values.
        processed = {}
        for key, val in node_repr.items():
            processed[key] = _process_node(val, current_path, path_stack)
        return processed

    # Start processing from the root dictionary.
    try:
        return _process_node(parser_dict, os.getcwd(), tuple())
    except Exception as exc:
        raise RuntimeError("Failed to resolve includes in parser dict") from exc

